solution.game_of_life.zig:
const std = @import("std");

/// Rectangular row-major board; returns a fresh generation with finite boundaries.
pub fn tick(allocator: std.mem.Allocator, cells: []const u8, rows: usize, cols: usize) ![]u8 {
    if (cells.len != rows*cols) return error.InvalidDimensions;
    for(cells) |cell| if(cell>1) return error.InvalidCell;
    const out=try allocator.alloc(u8,cells.len);
    for(0..rows) |r| for(0..cols) |c| {
        var count: u8=0;
        const r0=if(r==0) 0 else r-1; const c0=if(c==0) 0 else c-1;
        for(r0..@min(rows,r+2)) |nr| for(c0..@min(cols,c+2)) |nc| {
            if(nr!=r or nc!=c) count+=cells[nr*cols+nc];
        };
        out[r*cols+c]=@intFromBool(count==3 or (cells[r*cols+c]==1 and count==2));
    };
    return out;
}

tests.test_game_of_life.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("game_of_life.zig");

fn check(input:[]const u8,rows:usize,cols:usize,expected:[]const u8) !void {
    const out=try m.tick(a,input,rows,cols); defer a.free(out); try t.expectEqualSlices(u8,expected,out);
}
test "birth, survival, loneliness, overcrowding and finite boundaries" {
    try check(&.{},0,0,&.{}); try check(&.{1},1,1,&.{0});
    try check(&.{0,0,0,0,1,0,0,1,0},3,3,&.{0,0,0,0,0,0,0,0,0});
    try check(&.{0,1,0,0,1,0,0,1,0},3,3,&.{0,0,0,1,1,1,0,0,0});
    try check(&.{1,1,1,1,1,1,1,1,1},3,3,&.{1,0,1,0,0,0,1,0,1});
    try check(&.{1,1,0,1,1,0},2,3,&.{1,1,0,1,1,0});
    try t.expectError(error.InvalidDimensions,m.tick(a,&.{1},2,2));
}
